// Formateador de moneda dinámico
const formatCurrency = (amount: number, currency: string = 'ARS') => {
  const safeAmount = isNaN(amount) ? 0 : amount;
  return new Intl.NumberFormat('es-AR', {
    style: 'currency',
    currency: currency,
    minimumFractionDigits: 2,
  }).format(safeAmount);
};

